from pathlib import Path
import hashlib,json,math
import sys
root=Path(sys.argv[1]).absolute()
def read(name,expected=None):
 p=root/name;b=p.read_bytes()
 if expected:assert len(b)==expected[0] and hashlib.sha256(b).hexdigest()==expected[1]
 return json.loads(b)
def pin(name):
 p=root/name;b=p.read_bytes();return dict(path=str(p),bytes=len(b),sha256=hashlib.sha256(b).hexdigest())
def q(v):return {name:math.ceil(v[name]['upperNs']/1e6) for name in ('p50','p95','p99')}
v=read('independent-native-verdict-01.json',(int(sys.argv[2]),sys.argv[3]));assert v['nativePairQualified'] and v['slotReturned'] and not v['sustainedTPSQualified'] and v['firstCause'] is None
phases=read('original-business-checkpoint-phases-01.json');assert pin('original-business-checkpoint-phases-01.json')==v['originalNodeParserAuditReused']
recovery=read('complete-original-public-recovery.json');assert pin('complete-original-public-recovery.json')==v['originalPublicRecovery'];assert recovery['members']==549 and recovery['bytes']==44128502 and recovery['networkRangeBytes']==0 and recovery['httpRequests']==0
cases=[]
for index,name in enumerate(('before-native-replay-procs1','after-native-replay-procs2')):
 c=v['cases'][index];audit=phases['cases'][index];assert audit['name']==name
 raw=read('capture/'+name+'/network/transactions-result.json');r=read('capture/'+name+'/evidence/actual.json');joinname=name+'-node-completion-01.json';j=read(joinname);assert j['sourceCommit']==v['sourceCommit'] and j['runId']==v['runId'] and j['originalNodeAuditReused']==v['originalNodeParserAuditReused'];assert j['join']['records']==8192 and j['originalClientSHA256']==r['resultSHA256']
 for k in ('submissionUnknown','timedOut','executionFailed','observationFailed','checkTxRejected'):assert c['summary'][k]==0
 assert c['summary']['finalSubmitted']==8192 and raw['gomaxprocs']==1+index
 clock=c['measurement']['timeSeries'];pending=[b['offeredNotYetFinal'] for b in clock['buckets']];prefix=raw['durableReadback']['prefixReplay']['workPhases']
 latency={k:q(d) for k,d in c['measurement']['offerLatencyIntervalsNs'].items()};latency.update({k:q(d) for k,d in j['join']['nodeCompletionLatencyIntervalsNs'].items()});latency.update({k:q(d) for k,d in j['replicaJoin'].items()})
 cases.append(dict(name=name,clientGOMAXPROCS=1+index,nodeGOMAXPROCS=1,effectiveFinalTransactions=8192,actualOfferRate=c['summary']['offeredInterarrivalRate'],finiteFinalRate=c['summary']['finalSubmittedPerMeasurementSecond'],measurementWindowSeconds=c['summary']['measurementWindowSeconds'],businessErrors={k:c['summary'][k] for k in ('submissionUnknown','timedOut','executionFailed','observationFailed','checkTxRejected')},diagnosticErrorFactOccurrences=c['summary']['errorOccurrences'],processCPU=c['processCPU'],sampledPeaks=c['sampledPeaks'],oneSecondBucketEndPendingMaximum=max(pending),finalPending=pending[-1],readerGate=raw['durableReadback']['readerGate'],readbackPhasesNs=raw['durableReadback']['phaseTotalsNs'],prefixReplayPhases=prefix,replayNativeVerificationFacts=raw['durableReadback']['blockJournalNativeVerificationFacts'],supply=c['supply'],latencyUpperBoundsMs=latency,maximumClockCalibrationErrorBoundNs=j['join']['maximumCalibrationErrorBoundNs'],businessBlocksPerReplica=audit['nodes'][0]['businessBlocks'],meanTransactionsPerBusinessBlock=8192/audit['nodes'][0]['businessBlocks'],businessCommitPhases=audit['pooledReplicaSamples'],checkpointPhasesIncludingEmptyBlocks=audit['checkpointPhases'],nodeCompletionEvidence=pin(joinname)))
result=dict(schema=1,runId=40183256447,sourceCommit=v['sourceCommit'],codeCommit='50aae532583951fe728c6d67681ce5b6095a6b52',nativePairQualified=True,slotReturned=True,sustainedTPSQualified=False,defaultPromotionQualified=False,jointObservation=v['jointObservation'],cases=cases,finiteFinalRateChangePercent=(cases[1]['finiteFinalRate']/cases[0]['finiteFinalRate']-1)*100,actualOfferRateChangePercent=(cases[1]['actualOfferRate']/cases[0]['actualOfferRate']-1)*100,originalEvidence={n:pin(n) for n in ('independent-native-verdict-01.json','complete-original-public-recovery.json','original-business-checkpoint-phases-01.json','paired-ci-full.raw','original-complete-run-api.json')},interpretation=['Same VM/source/four ELFs; only client scheduler1→2; nodes remain1; each8192 finite business inputs, not1000×600s.','Latency P50/P95/P99 are upper bounds from1ms bins; node completion calibration errors retained. Endpoint Finalize is executed completion, not proposal arrival; node Commit is durable completion; earliest BFT quorum formation unmeasured; third replica is not voting-power quorum.','Reader wait/load/decode, nested AppHash and checkpoint maintenance children overlap parents. Phase quantiles must not be added or subtracted.','Business block packing differs; compare per-block means with block sizes and cumulative totals. Four replicas are not fourfold business TPS.','Sampled RSS and one-second bucket-end pending maxima are not hard memory or instantaneous backlog peaks. Error-fact occurrences are repeated diagnostics, not failed business transactions.','Joint improvement must be read from the original pair observation. One finite pair and variable fsync do not establish a stable causal gain or authorize default promotion.'])
out=root/'qualified-metrics-and-node-completion-01.json'
with out.open('x') as f:json.dump(result,f,indent=2);f.write('\n')
print(json.dumps(dict(finalRateChangePercent=result['finiteFinalRateChangePercent'],offerRateChangePercent=result['actualOfferRateChangePercent'],output=pin(out.name))))
